#!/usr/bin/env python3
"""Certified sharing replay entry point.

Reads one UTF-8 JSON request from stdin to EOF, validates the WHOLE request
(including the transactions that follow restores), replays every case and
writes a single compact JSON response to stdout.  Diagnostics go to stderr.
"""
import json
import math
import os
import sys

_HERE = os.path.dirname(os.path.abspath(__file__))
if _HERE not in sys.path:
    sys.path.insert(0, _HERE)

MAX_BYTES = 8 * 1024 * 1024


def _emit_float(value, out):
    if value != value or value in (math.inf, -math.inf):
        raise ValueError('non-finite numeric result')
    if value == 0.0:
        out.append('0.0')
    else:
        out.append(repr(value))


def _emit(value, out):
    kind = type(value)
    if kind is dict or isinstance(value, dict):
        out.append('{')
        first = True
        for key, item in value.items():
            if not first:
                out.append(',')
            first = False
            out.append(json.dumps(key))
            out.append(':')
            _emit(item, out)
        out.append('}')
    elif kind is list or isinstance(value, (list, tuple)):
        out.append('[')
        for index, item in enumerate(value):
            if index:
                out.append(',')
            _emit(item, out)
        out.append(']')
    elif kind is bool or isinstance(value, bool):
        out.append('true' if value else 'false')
    elif kind is float or isinstance(value, float):
        _emit_float(float(value), out)
    elif kind is int or isinstance(value, int):
        out.append(str(int(value)))
    elif value is None:
        out.append('null')
    elif isinstance(value, str):
        out.append(json.dumps(value))
    elif hasattr(value, 'tolist'):          # numpy scalar/array
        _emit(value.tolist(), out)
    else:
        raise TypeError('unsupported result value')


def serialize(value):
    out = []
    _emit(value, out)
    return ''.join(out)


def solve(request):
    from te.session import run_case
    return {'cases': [run_case(case) for case in request['cases']]}


def read_request():
    """Read the whole request from standard input, to EOF."""
    stream = getattr(sys, 'stdin', None)
    buffered = getattr(stream, 'buffer', None) if stream is not None else None
    if buffered is not None:
        try:
            return buffered.read()
        except Exception:
            pass
    if stream is not None:
        try:
            fd = stream.fileno()
        except Exception:
            fd = 0
        chunks = []
        try:
            while True:
                block = os.read(fd, 1 << 20)
                if not block:
                    break
                chunks.append(block)
            return b''.join(chunks)
        except Exception:
            try:
                return stream.read()
            except Exception:
                return b''
    return b''


def main():
    raw = read_request()
    result = None
    try:
        from protocol import InvalidRequest, loads, validate
        try:
            result = solve(validate(loads(raw)))
        except InvalidRequest:
            result = {'error': 'invalid_request'}
    except BaseException:                     # pragma: no cover - safety net
        result = {'error': 'invalid_request'}
    try:
        text = serialize(result)
    except BaseException:                     # pragma: no cover - safety net
        text = '{"error":"invalid_request"}'
    sys.stdout.write(text)
    sys.stdout.write('\n')
    sys.stdout.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())
